def handle(q: str) -> Reply:
    msgs = build_context(q, search_docs(q))  # (가)
    for turn in range(MAX_TURNS):  # (나)
        msg = with_retry(client.messages.create,  # (다)
            model=MODEL, timeout=30, ...)  # (라)
        spent_usd += cost_of(msg.usage)  # (마)
        if spent_usd > BUDGET_USD: raise BudgetExceeded
        log_jsonl(msg._request_id, msg.usage)  # (바)
        if msg.stop_reason != "tool_use":
            return Reply.model_validate_json(...)  # (사)
        for b in tool_uses(msg):
            if b.name == "create_ticket": approve(b)  # (아)
            msgs += execute_tool(b)  # (자)
        save_checkpoint(msgs)  # (차)
